"""Task-oriented interface over the existing atlas, keeping IDs and data contracts."""
import json
import re
from web_accessibility import group_panels, externalize
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
BASE=ROOT/'tools'/'seeds'/'revision-5.9'


def patch(s,old,new):
    if old not in s:raise ValueError('Missing UI patch: '+old[:90])
    return s.replace(old,new)


def section(source,id):
    return re.search(r'<section class="tab" id="tab-'+id+r'">.*?</section>',source,re.S).group(0)


def build(d):
    source=(BASE/'index.html').read_text();tabs={id:section(source,id) for id in ['overview','3d','plan','terrain','rooms','material','build','storage','system','steps']}
    version=d['meta']['version']
    count=lambda n:f'{n:,}'.replace(',','.')
    groups=[('start','Start','overview','M3 10L12 3l9 7v11h-6v-7H9v7H3Z'),('atlas','Bauatlas','3d','M12 3l9 5v8l-9 5-9-5V8Zm0 10v8M3 8l9 5 9-5'),('terrain','Gelände','terrain','M2 20l7-14 5 9 3-5 5 10Z'),('storage','Lager','storage','M3 7l9-4 9 4v13H3Zm0 0h18M8 11h8M8 16h8'),('organize','Organisation','build','M8 5H5v16h14V5h-3M9 3h6v5H9Zm0 10l2 2 4-4')]
    nav=''.join(f'<button data-tab="{tab}" data-group="{g}" id="btn-area-{g}" role="tab" aria-selected="{str(g=='start').lower()}" tabindex="{0 if g=='start' else -1}" aria-controls="area-{g}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="{icon}"/></svg><span>{name}</span></button>' for g,name,tab,icon in groups)
    subgroups={'atlas':[('3d','3D-Modell'),('structure','Hausstruktur'),('viewer','Minecraft-Texturen'),('plan','Ebenenplan'),('steps','Bauen & Abhaken'),('rooms','Räume'),('lighting','Leuchten')],
        'terrain':[('terrain','Karte & Erdarbeiten')], 'storage':[('storage','Bestände'),('system','Sortierung & Technik')],
        'organize':[('live','Live-Baufortschritt'),('build','Lokale Bauhäkchen'),('material','Materialbedarf'),('shared','Gemeinsame Liste'),('downloads','Dateien & Berichte')]}
    subnav=''.join(f'<div data-subgroup="{g}" role="tablist" aria-label="Ansichten {g}" hidden>'+''.join(f'<button id="btn-view-{id}" role="tab" aria-selected="false" tabindex="-1" data-tab="{id}" aria-controls="tab-{id}">{label}</button>' for id,label in items)+'</div>' for g,items in subgroups.items())
    scope_data=d['material_scopes'];items=lambda key:sum(scope_data[key]['counts'].values())
    material_notice=f'<div class="notice"><p id="materialScopeNote" role="status">Haus und Keller ohne Gelände und Nebengebäude.</p><p><b>{count(items("house"))} Items Haus und Keller</b> · {count(items("outdoor"))} Außenanlagen und Nebengebäude · {count(items("terrain"))} Gelände. Die große Erd- und Bruchsteinmenge liegt in der Auffüllung.</p><p>Die Mengen beschreiben den Zielplan. Vorhandene Blöcke und wiederverwendbarer Aushub reduzieren den zusätzlich zu beschaffenden Bedarf. Erdarbeitslisten nicht nochmals zur Gesamtmaterialliste addieren.</p><a href="materialpruefung.md">Ausführlicher Prüfbericht</a> · <a href="materialbedarf_bestandsvergleich.csv" download>Vergleich mit altem Weltstand</a></div>'
    tabs['material']=tabs['material'].replace('  <div class="stats"',material_notice+'  <div class="stats"',1).replace('Gesamt als CSV','Auswahl als CSV').replace('Material nach Baugruppe','Materialbereich oder Baugruppe')
    tabs['material']=re.sub(r'<p class="muted">Zahlen sind Items, nicht Blöcke:.*?</p>', '<p class="muted">Türen und Betten zählen je einmal. Flüssigkeiten und bewegte Kolbenköpfe sind keine zusätzlichen Items. Ein doppelter Plattenblock benötigt zwei Platten. Geeignete Steintreppen: Steinsäge 1 zu 1, Werkbank 6 Vollblöcke zu 4 Treppen. Platten: jeweils 1 Vollblock zu 2 Platten. Einrichtung und originale Lager-Litematics haben separate Materiallisten.</p>',tabs['material'],flags=re.S)
    tabs['material']=tabs['material'].replace('<div class="notice">','<div class="notice"><p><button type="button" class="btn primary" data-tab="shared">Gemeinsam sammeln und abhaken →</button></p>',1)
    oldstats=re.search(r'<div class="stats overview-stats">.*?</div>\s*<div class="facts" id="facts"></div>',tabs['overview'],re.S).group(0)
    material_items=sum(d['counts'].values())
    material_types=len(d['counts'])
    tabs['overview']=f'''<section class="tab" id="tab-overview">
      <div class="welcome"><div><span class="eyebrow">EUER VIKTORIANISCHES KLIPPENANWESEN</span><h2>Ein klarer Plan.<br>Schicht für Schicht zum Haus.</h2><p>Erkundet das Anwesen, wählt eure Bauhöhe und plant gemeinsam Material und Fortschritt.</p><div class="cta"><button class="btn primary" data-go="3d">Haus in 3D ansehen <span aria-hidden="true">↗</span></button><button class="btn" data-go="plan">Ebenenplan öffnen</button></div></div><a class="welcome-image" href="assets/anwesen_ost.png"><img src="assets/anwesen_ost.png" alt="Poolseite des aktuellen Blockmodells"><span>Poolseite · Blick nach Osten</span></a></div>
      <div class="section-heading"><h2>Womit möchtet ihr weitermachen?</h2><span class="muted">Alles an seinem Platz</span></div>
      <div class="task-grid"><article class="task-card"><span class="task-number">01 / BAUEN</span><h3>Die nächste Schicht</h3><p>Eine Welt-Höhe auswählen, Blöcke nachschlagen und gesetzte Positionen abhaken.</p><button class="text-button" data-go="steps">Zur Baubegleitung →</button></article><article class="task-card"><span class="task-number">02 / VORBEREITEN</span><h3>Das Gelände planen</h3><p>Original und Ziel vergleichen. Abtrag und Auffüllung mit genauen Koordinaten lesen.</p><button class="text-button" data-go="terrain">Zu den Erdarbeiten →</button></article><article class="task-card"><span class="task-number">03 / GEMEINSAM</span><h3>Material gemeinsam sammeln</h3><p>Bestände, Häkchen und Lagerplätze im Team aktualisieren. Alle sehen denselben Stand.</p><button class="text-button" data-go="shared">Gemeinsame Liste öffnen →</button></article></div>
      <div class="start-summary"><div><span class="status-dot"></span><b id="homeProgress">Fortschritt wird geladen</b><span class="muted">in diesem Browser</span></div><button class="text-button" data-go="material">Materialbedarf ansehen →</button></div>
      <details class="card project-details"><summary>Projektdaten &amp; Prüfstand <span class="muted">Revision {version} · Java 26.3</span></summary>{oldstats}<div id="checks"></div><a href="analysebericht.md">Änderungen dieser Revision lesen</a></details>
    </section>'''
    material_glance=f'''<div class="card material-glance"><div><span class="eyebrow">BAUMATERIAL</span><b class="material-total">{count(material_items)} Items</b><span class="muted">laut Materialliste · {count(material_types)} Sorten</span></div><button class="btn primary" data-go="material">Zur vollständigen Materialliste →</button></div>'''
    tabs['overview']=tabs['overview'].replace('      <details class="card project-details">','      '+material_glance+'\n      <details class="card project-details">')
    # 3D controls: one floor choice, one height slider, clear camera shortcuts.
    a=tabs['3d'].index('  <div class="toolbar">');z=tabs['3d'].index('  <div class="viewer">',a)
    tabs['3d']=tabs['3d'][:a]+f'''<div class="scene-controls"><div class="toolbar"><div class="button-group" aria-label="Kamera"><button class="mini" data-cam="iso">Anwesen</button><button class="mini" data-cam="east">Poolseite</button><button class="mini" data-cam="west">Eingang</button><button class="mini" data-cam="estate">Gesamtgelände</button></div><details class="camera-options"><summary>Weitere Ansichten</summary><div><button class="mini" data-cam="north">Nord</button><button class="mini" data-cam="south">Süd</button><button class="mini" data-cam="top">Draufsicht</button></div></details><span class="sp"></span><button class="mini" id="resetScene">Ansicht zurücksetzen</button></div>
      <div class="toolbar"><label>Etage <select id="sceneFloor"><option value="{d['meta']['bbox'][3]}">Gesamtes Haus</option><option value="144">Obergeschoss</option><option value="136">Erdgeschoss</option><option value="128">Keller 1</option><option value="120">Keller 2</option><option value="112">Keller 3</option><option value="custom" disabled>Eigene Höhe</option></select></label><div class="slider"><button class="mini" id="cutDown" aria-label="Eine Ebene tiefer">−</button><input type="range" id="cut" step="1" aria-label="3D-Schnitthöhe"><button class="mini" id="cutUp" aria-label="Eine Ebene höher">+</button><b id="cutLabel">Y</b></div><label class="chk"><input type="checkbox" id="single"><span>Nur diese Ebene</span></label></div>
      <div class="toolbar terrain-controls"><label class="chk"><input type="checkbox" id="terrainChk" checked><span>Gelände anzeigen</span></label><select id="terrainState" aria-label="Geländezustand"><option value="target">Geplantes Gelände</option><option value="original">Originalgelände</option><option value="work">Erdarbeiten farbig</option></select><small class="muted">Ziehen: drehen · Shift: verschieben · Mausrad: zoomen</small></div></div>'''+tabs['3d'][z:]
    if version.startswith('6.'):
        tabs['3d']=tabs['3d'].replace('value="128">Keller 1','value="128">Porter-Galerie').replace('value="120">Keller 2','value="123">Großlager').replace('value="112">Keller 3','value="101">Geheimräume')
    tabs['3d']=tabs['3d'].replace('<details open>','<details>').replace('<div class="hint">ziehen = drehen · Rechtsklick = verschieben · Rad = zoomen</div>','')
    tabs['3d']=tabs['3d'].replace('<canvas id="gl"></canvas>','<canvas id="gl"></canvas><div id="detailBanner" class="detail-banner" hidden><span>Leuchtendetail · mit Träger und Kette</span><button class="mini" id="leaveDetail">Zur Hausansicht</button></div>')
    terrain=(ROOT/'tools/terrain_section.html').read_text()
    sites=''.join(f'<article class="card outdoor-card"><span class="eyebrow">AUSSENANLAGEN</span><a class="outdoor-image" href="assets/{["ankunftsgarten.png","garten_sued.png","aussen_v6.png"][min(i,2)]}"><img src="assets/{["ankunftsgarten.png","garten_sued.png","aussen_v6.png"][min(i,2)]}" alt="Modellvorschau {site["name"]}" loading="lazy"></a><h3>{site["name"]}</h3><p>{site["text"]}</p><button class="text-button" data-outdoor="{i}">Garten in 3D ansehen →</button></article>' for i,site in enumerate(d['outdoor_sites']))
    for key,value in {'CUT':count(d['terrain']['excavate_total']),'FILL':count(d['terrain']['fill_total']),'SKIN':count(d['landscape_changes']['columns']),'SITES':sites}.items():terrain=terrain.replace('@'+key+'@',value)
    tabs['terrain']=terrain
    viewer=(ROOT/'tools/viewer_section.html').read_text().replace('@BLOCKS@',count(d['meta']['total'])).replace('@VERSION@',version)
    # The warehouse becomes one searchable list rather than 56 large cards.
    tabs['storage']='''<section class="tab" id="tab-storage"><div class="page-intro"><h2>Wo liegt welches Material?</h2><p>50 Regallagerbuchten und sechs Privatreserven. Kategorien durchsuchen, Bestände notieren und die Position im Ebenenplan öffnen.</p></div><div class="toolbar"><input type="search" id="storageQuery" aria-label="Lagerbuchten suchen" placeholder="Kategorie, Bucht oder Bereich suchen …"><span class="sp"></span><button class="mini" onclick="__openGroup('lager_regale')">Regallager in 3D</button><button class="mini" id="storageExport">Bestandsliste exportieren</button></div><div class="list-summary" id="storageSummary" role="status"></div><div class="tw"><table><thead><tr><th>Bucht</th><th>Kategorie / Bereich</th><th>Kapazität</th><th>Notiz / tatsächlicher Bestand</th><th>Position</th></tr></thead><tbody id="storageZones"></tbody></table></div><div class="storage-footer"><details><summary>Bestandsnotizen zurücksetzen</summary><p>Dies betrifft nur die manuell eingetragenen Lagerbestände.</p><button class="btn" id="storageReset">Bestände zurücksetzen</button></details><button class="text-button" data-go="system">Sortierung &amp; Technik ansehen →</button></div></section>'''
    # Long technical context stays available, with the working map and summary first.
    system=tabs['system']
    hero=re.search(r'<div class="hero">.*?</div></div>',system,re.S).group(0)
    flow=re.search(r'<div class="sys-flow">.*?</div></div>',system,re.S).group(0)
    # Preserve all module/simulation IDs used by system.js; fold text-heavy groups.
    body=system[system.index('<div class="grid2">'):system.rfind('</section>')]
    body=body.replace('<div class="grid2"><div class="card"><h2>Bulk: zuerst Vorrat, dann Verpackung</h2>', '<div class="grid2"><details class="card"><summary>Bulk-Lager · Module und Vorratspriorität</summary>')
    body=body.replace('<div id="sysBulk"></div></div><div class="card"><h2>Kupfergolems: konkrete Typen statt Etiketten</h2>', '<div id="sysBulk"></div></details><details class="card"><summary>Kupfergolems · Zieltruhen und Seed-Items</summary>')
    body=body.replace('<div id="sysRegular"></div></div></div>', '<div id="sysRegular"></div></details></div>')
    modules=json.loads((ROOT/'lagertechnik_module.json').read_text())
    module_cards=''.join(f'''<article class="card module-card"><span class="eyebrow">LITEMATICA · {m['author']}</span><h3>{m['name']}</h3><p><b>{count(m['total_blocks'])} Blöcke</b> · {m['bounds_size'][0]} × {m['bounds_size'][1]} × {m['bounds_size'][2]} · {count(m['entity_total'])} Entities · {count(m['block_entity_total'])} Blockentities</p><p>Vorschlagsanker X {m['proposed_world_anchor'][0]} · Y {m['proposed_world_anchor'][1]} · Z {m['proposed_world_anchor'][2]} · ohne Drehung</p><div class="viewer-actions"><button class="btn primary" data-preview-module="{m['key']}">Texturansicht öffnen</button><a class="btn" href="litematics/{m['source']}" download>Original-Litematic ↓</a></div><details><summary>Materialbedarf der Vorlage</summary><div class="module-materials">{''.join(f'<span><code>{bid}</code><b>{count(amount)}</b></span>' for bid,amount in list(m['materials'].items())[:14])}</div><p class="muted">Alle {len(m['materials'])} Blocksorten stehen in der Litematic; vollständige Vorlage herunterladen.</p></details></article>''' for m in modules['modules'])
    vault=modules['vault']
    service_shaft=d['structure']['service_shaft']
    module_section=f'''<div class="section-heading"><h2>Mitgelieferte Lagersysteme</h2><span class="muted">Vorschlag für den Technikstollen</span></div><div class="module-grid">{module_cards}</div><div class="notice module-plan"><b>Einbauvorschlag unter Keller 3</b><p>Die kombinierte Grundfläche ist X {vault['bounds'][0]}…{vault['bounds'][1]}, Z {vault['bounds'][4]}…{vault['bounds'][5]} (57 × 27) bei Y {vault['bounds'][2]}…{vault['bounds'][3]} (24 hoch). Der {count(vault['service_gap_x'][1]-vault['service_gap_x'][0]+1)} Blöcke breite Wartungsspalt liegt bei X {vault['service_gap_x'][0]}…{vault['service_gap_x'][1]}; die vorgeschlagene Schachtachse liegt bei X {vault['shaft_target'][0]} / Z {vault['shaft_target'][2]}. Diese Grube und die Verbindung der Itemwege sind noch nicht Teil der Bau-Blockliste; die Vorschlagskoordinaten stehen in <a href="lagertechnik_platzierung.csv" download>lagertechnik_platzierung.csv</a>.</p><p>Die Schaltungen stammen aus den Original-Litematics von cubicmetre. Sie werden im Viewer unverändert gezeigt; Verknüpfung mit Einwurf, Bulk-Lager und Shulker-Ausgabe bleibt vor dem Einbau im Spiel zu prüfen.</p></div>'''
    tabs['system']='''<section class="tab" id="tab-system"><div class="page-intro"><h2>Einwurf, Sortierung und Reserven</h2><p>Paper 26.3 · Technikentwurf und originale Copper-Golem-Module. Anschlüsse und Redstone-Abnahme im Spiel stehen noch aus.</p></div><div class="toolbar"><button class="btn" id="sysGotoInput">Einwurf im Plan</button><button class="btn" id="sysGotoTrade">Trading Hall</button><a class="btn" href="technik_inbetriebnahme.md">Schaltplan &amp; Testfolge</a></div>'''+module_section+flow+body+'</section>'
    # Secondary pages retain the proven event/data IDs, with shorter introductory copy.
    tabs['steps']=tabs['steps'].replace('Baubegleitung nach Welt-Höhe','Eine Schicht nach der anderen').replace('Revision 5.9',f'Revision {version}')
    tabs['build']=tabs['build'].replace('Bauplan</h2>','Baufortschritt</h2>')
    lighting='''<section class="tab" id="tab-lighting"><div class="page-intro"><h2>Leuchten, die ihren Platz haben</h2><p>Bodenleuchten aus Durchgängen entfernt, kurze Deckenaufhängungen ergänzt. Originale Kronleuchter und Terrassenleuchten bleiben erhalten.</p></div><div class="lighting-summary"><div class="stat"><b>'''+str(d['lighting']['total'])+'''</b><span>geplante Leuchten</span></div><div class="stat"><b>max. '''+str(d['lighting']['max_chain'])+'''</b><span>Kettenblöcke je Leuchte</span></div><div class="stat"><b>'''+str(len(d['lighting']['fixtures']))+' / '+str(len(d['lighting']['fixtures']))+'''</b><span id="attachmentCount">Anschlüsse geprüft</span></div></div><div class="notice">Geprüft: Träger, durchgehende Ketten und freie Durchgänge. Eine Licht-/Spawn-Simulation steht weiterhin aus.</div><div class="toolbar"><input type="search" id="lightQuery" aria-label="Leuchten suchen" placeholder="Raum, Block-ID oder XYZ suchen …"><select id="lightLevel" aria-label="Leuchten nach Etage"><option value="all">Alle Höhenbereiche</option></select><select id="lightKind" aria-label="Leuchten nach Montage"><option value="all">Alle Montagearten</option><option value="hanging">Hängend</option><option value="standing">Auf Sockel / Möbel</option></select><span class="sp"></span><a class="mini" href="laternen_pruefung.csv" download>Leuchtenplan als CSV</a></div><div class="list-summary" id="lightSummary" role="status"></div><div class="tw"><table><thead><tr><th>Leuchte</th><th>Bereich</th><th>Weltkoordinate</th><th>Montage / Träger</th><th>Ansehen</th></tr></thead><tbody id="lightRows"></tbody></table></div><details class="card" style="margin-top:18px"><summary>Was wurde an den Laternen geändert?</summary><p>Die alte automatische Verteilung stellte viele Leuchten in begehbare Bodenebenen. Diese Positionen und ungenutzte Ketten wurden entfernt. Neue, sparsam gesetzte Deckenleuchten haben höchstens zwei Kettenblöcke. Metallrahmen, Bügel und warmes bzw. blaues Licht werden getrennt gezeichnet; die Seitenansicht im Ebenenplan sitzt ebenfalls auf der richtigen Höhe.</p><p>Die Leuchtenliste führt jede vorhandene Laterne mit tatsächlicher Position und Träger auf. „3D“ öffnet eine isolierte Detailansicht mit Leuchte, Kette und Träger. „Ganzes Haus“ kehrt zur Gesamtansicht zurück.</p><div class="lamp-examples"><a href="assets/laterne_pendant.png"><img src="assets/laterne_pendant.png" alt="Modell einer Laterne mit zwei Kettenblöcken und Deckenanker" loading="lazy"><span>Kurze Deckenaufhängung</span></a><a href="assets/laterne_standing.png"><img src="assets/laterne_standing.png" alt="Modell einer Laterne auf festem Sockel" loading="lazy"><span>Laterne auf einem Sockel</span></a></div></details></section>'''
    lighting=lighting.replace('236 / 236',f"{d['lighting']['total']} / {d['lighting']['total']}")
    downloads='''<section class="tab" id="tab-downloads"><div class="page-intro"><h2>Die passenden Dateien für eure Aufgabe</h2><p>Bauplan und lokale Bauhäkchen funktionieren offline. Die gemeinsame Materialliste benötigt die veröffentlichte Website und eine Internetverbindung. CSV-Dateien lassen sich in Tabellenprogrammen öffnen; vollständige Fortschritts-Backups findet ihr unter Organisation → Fortschritt.</p></div><div class="download-grid">'''
    categories=[('Haus bauen',[('blockliste.csv','Alle Blockpositionen'),(f"blackthorn_estate_{version}.nbt",'Minecraft-Struktur für den Structure Viewer'),('materialbedarf.csv','Gesamtplan inklusive Gelände'),('materialbedarf_haus.csv','Nur Haus und Keller'),('materialbedarf_aussenanlagen.csv','Außenanlagen und Nebengebäude'),('materialbedarf_gelaende.csv','Gelände und Auffüllung'),('materialpruefung.md','Block- und Materialprüfung'),('materialbedarf_baugruppen.csv','Material je Bauteil'),('laternen_pruefung.csv','Leuchten und Träger'),(f"aenderungen_{d['progress_compat']['revision']}_zu_{version}.csv",'Änderungen dieser Revision')]),
        ('Lagertechnik',[('litematics/Copper Golem MIS Cherry.litematic','Copper Golem MIS Cherry · cubicmetre'),('litematics/Golem MIS Dustless Filter.litematic','Golem MIS Dustless Filter · cubicmetre'),('lagertechnik_platzierung.csv','Vorgeschlagene Einbaukoordinaten')]),
        ('Gelände vorbereiten',[('terraforming.csv','Ist-/Soll-Spalten'),('terraforming_chunks.csv','Arbeit je Minecraft-Chunk'),('assets/terraforming_vergleich.png','Geländevergleich als Bild'),('aussendekoration.csv','Garten und Außendekoration'),('aushub_blockliste.csv','Älterer Geländeentwurf: Abtrag'),('auffuellung_blockliste.csv','Älterer Geländeentwurf: Auffüllung'),('vegetation_entfernen.csv','Vegetation räumen'),('bestandskonflikte.csv','Vorhandene Bauten prüfen')]),
        ('Lager einrichten',[('lagerbuchten.csv','Manuelle Lagerbuchten'),('technik_module.csv','Technische Module'),('technik_inventare.csv','Filter- und Seed-Inventare'),('technik_inbetriebnahme.md','Schaltphasen und Abnahme')]),
        ('Projekt nachlesen',[('README.md','Öffnen und Bedienen'),('analysebericht.md','Änderungen und Prüfgrenzen'),('check_report.json','Modellprüfung'),('pruefprotokoll.json','Ausgeführte Prüfungen')])]
    for heading,files in categories:downloads+='<article class="card"><h3>'+heading+'</h3><ul class="file-list">'+''.join(f'<li><a href="{file}" download><span>{label}</span><small>{file.split(".")[-1].upper()} ↓</small></a></li>' for file,label in files)+'</ul></article>'
    downloads+='</div></section>'
    level_cards=''.join(f'<article class="card level-card"><div class="level-card-head"><span class="eyebrow">{level["height"]} Y-EBENEN</span><b>Y {level["y"][0]}–{level["y"][1]}</b></div><h3>{level["label"]}</h3><p>{count(level["positions"])} Baupositionen · {len(level["rooms"])} Raumbezüge</p><div class="level-rooms">{", ".join(level["rooms"]) or "Keine Räume"}</div><button class="mini" data-level-cut="{level["y"][1]}">Diesen Schnitt in 3D öffnen →</button></article>' for level in d['structure']['levels'])
    axis_cards=''.join(f'<article class="axis-card"><span class="eyebrow">X {axis["x"][0]} … {axis["x"][1]}</span><h3>{axis["label"]}</h3><button class="mini" data-axis-group="{axis["groups"][0]}">Bereich im 3D-Modell öffnen →</button></article>' for axis in d['structure']['axes'])
    stair_rows=''.join(f'<li><b>{stair["label"]}</b><span>{stair["blocks"]} Treppenblöcke · X {stair["x"][0]}…{stair["x"][1]} · Y {stair["y"][0]}…{stair["y"][1]}</span></li>' for stair in d['structure']['stair_runs'])
    logistics_rows=''.join(f'<li><b>{row["label"]}</b><span>Y {row["y"][0]}…{row["y"][1]}</span></li>' for row in d['structure']['logistics'])
    clearance_rows=''.join(f'<li><b>{audit["group"]}</b><span>{audit["stair_blocks"]} Stufen · {audit["obstructed_positions"]} von {audit["clearance_blocks"]} Kopfraumebenen belegt</span></li>' for audit in d['structure']['stair_clearance'])
